#[test]
fn state_matches_c() {
    unsafe {
        let want = include_str!("data/gro_grcastle.txt");
        let mut lines = want.lines();
        let verbose = std::env::var("ORACLE_VERBOSE").ok(); if verbose.is_some() { DUMP_N = core::mem::size_of::<Ground>(); }
        let hdr: std::vec::Vec<usize> = lines.next().unwrap().split_whitespace().skip(1).map(|s| s.parse().unwrap()).collect();
        let sizes: std::vec::Vec<usize> = std::vec![core::mem::size_of::<Ground>(), core::mem::size_of::<HSD_GObj>(), core::mem::size_of::<HSD_JObj>(), core::mem::size_of::<StageInfo>(), core::mem::size_of_val(&*addr_of!(t::yakumono_param)), core::mem::size_of_val(&*addr_of!(t::grCs_804D6974)), core::mem::size_of_val(&*addr_of!(t::grCs_804D45E0)), core::mem::size_of_val(&*addr_of!(t::grCs_804D45E4)), core::mem::size_of_val(&*addr_of!(OWP)), core::mem::size_of_val(&*addr_of!(OCD)), core::mem::size_of_val(&*addr_of!(ODD)), core::mem::size_of_val(&*addr_of!(OAPP)), core::mem::size_of_val(&*addr_of!(t::grCs_StageCallbacks)), core::mem::size_of_val(&*addr_of!(t::grCs_StageData)), core::mem::size_of_val(&*addr_of!(t::grCs_803E0FE8)), core::mem::size_of_val(&*addr_of!(t::grCs_803E1198)), core::mem::size_of_val(&*addr_of!(t::grCs_803B7E9C)), core::mem::size_of_val(&*addr_of!(t::grCs_803B7EA8)), core::mem::size_of_val(&*addr_of!(t::grCs_803B7EB8)), core::mem::size_of_val(&*addr_of!(t::grCs_803B7EC8)), core::mem::size_of_val(&*addr_of!(t::grCs_803B7EF0)), core::mem::size_of_val(&*addr_of!(t::grCs_803B7EFC)), core::mem::size_of_val(&*addr_of!(t::grCs_803B7F28)), core::mem::size_of_val(&*addr_of!(t::grCs_803B7F3C)), core::mem::size_of_val(&*addr_of!(t::grCs_803B7F50))];
        assert_eq!(hdr, sizes, "struct sizes (C native layout vs the Rust port)");
        install_hooks();
        world_reg();
        world_reg_fns();
        let mut bad = std::vec::Vec::new();
        for (fi, fnn) in FNS.iter().enumerate() {
            let mut agg = FNV0;
            let vb = verbose.as_deref() == Some(fnn.name);
            DUMP_N = if vb { core::mem::size_of::<Ground>() } else { 0 };


            for k in 0..fnn.n {
                let mut h = FNV0;
                RS = 0x9E37_79B9u32 ^ ((fi as u32).wrapping_mul(7919).wrapping_add(k.wrapping_mul(104729)).wrapping_add(1));
                world_fill(fi);
                let mut a = core::mem::zeroed::<Args>();
                for i in 0..4 { a.i[i] = rnd() % 4; }
                for i in 0..2 { a.f[i] = rf(); }
                for i in 0..2 { a.v3[i].x = rf(); a.v3[i].y = rf(); a.v3[i].z = rf(); }
                for i in 0..2 { a.v2[i].x = rf(); a.v2[i].y = rf(); }
                for i in 0..2 { a.pf[i] = rf(); }
                for i in 0..2 { a.pi[i] = (rnd() % 8) as i32; }
                case_pre(fi, &mut a); if vb { println!("PRE"); world_hash(fi); println!("ENDPRE"); }
                LG.clear();
                let (rv, _rb) = call_fn(fi, &mut a);
                let ho = fnv(FNV0, LG.as_bytes());
                let hw = world_hash(fi);
                for x in [ho, rv, hw] {
                    h = fnv(h, &x.to_le_bytes());
                }
                h = fnv(h, &canon_f32_bytes(&[a.v3[0].x, a.v3[0].y, a.v3[0].z, a.v3[1].x, a.v3[1].y, a.v3[1].z]));
                h = fnv(h, &canon_f32_bytes(&[a.v2[0].x, a.v2[0].y, a.v2[1].x, a.v2[1].y]));
                h = fnv(h, &canon_f32_bytes(&a.pf));
                h = fnv(h, bytes(&a.pi));
                if vb {
                    let hs: std::vec::Vec<std::string::String> = WH.iter().map(|x| format!("{:x},", x & 0xFF_FFFF)).collect();
                    println!("{} {:016x} ret={:x} W={:016x} L={:016x} H={}
  {}", k, h, rv, hw, ho, hs.concat(), LG);
                    for q in 0..NGO { let mut line = format!("  OGP{}:", q); let base = addr_of!(OGP[q]) as *const u8; for w in (0..core::mem::size_of::<Ground>()).step_by(4) { line.push_str(&format!(" {:08x}", core::ptr::read_unaligned(base.add(w) as *const u32))); } println!("{}", line); }
                }
                agg = fnv(agg, &h.to_le_bytes());
            }
            if verbose.is_some() {
                continue;
            }
            let line = lines.next().expect("data file shorter than the function table");
            let (cname, chash) = line.split_once(' ').unwrap();
            assert_eq!(cname, fnn.name, "data file and function table out of step");
            if u64::from_str_radix(chash, 16).unwrap() != agg {
                bad.push(fnn.name);
            }
        }
        assert!(bad.is_empty(), "{} of {} functions differ from the C: {:?}", bad.len(), FNS.len(), bad);
    }
}
